cd /workspace && node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Get all unique routes
const flights = db.prepare(\"SELECT DISTINCT origin, destination FROM flights WHERE source_skill='tau2Airline'\").all();
console.log('Available direct routes:');
flights.forEach(f => console.log('  ' + f.origin + ' -> ' + f.destination));

console.log('\nAll unique airports:');
const airports = new Set();
flights.forEach(f => { airports.add(f.origin); airports.add(f.destination); });
console.log('  ' + [...airports].sort().join(', '));

// Now find all possible one-stop connections
console.log('\nAll possible one-stop routes:');
const flightsFull = db.prepare(\"SELECT flight_id, origin, destination, departure_time, arrival_time, cabin_prices_json, dates_json FROM flights WHERE source_skill='tau2Airline'\").all();

// Build adjacency
const routes = {};
for (const f of flightsFull) {
  const key = f.origin;
  if (!routes[key]) routes[key] = [];
  routes[key].push(f);
}

// Find one-stop options (all pairs)
const oneStopPairs = new Set();
for (const f1 of flightsFull) {
  const connecting = routes[f1.destination] || [];
  for (const f2 of connecting) {
    if (f2.destination !== f1.origin) { // no same-origin return
      const pair = f1.origin + ' -> ' + f1.destination + ' -> ' + f2.destination;
      if (!oneStopPairs.has(pair)) {
        oneStopPairs.add(pair);
        // Check time compatibility (arrival of f1 < departure of f2)
        const arr1 = f1.arrival_time;
        const dep2 = f2.departure_time;
        const timeOk = (!arr1 || !dep2 || arr1 <= dep2) ? 'time OK' : 'time conflict';
        const prices1 = JSON.parse(f1.cabin_prices_json);
        const prices2 = JSON.parse(f2.cabin_prices_json);
        console.log('  ' + pair);
        console.log('    Leg 1: ' + f1.flight_id + ' dep:' + (f1.departure_time||'?') + ' arr:' + (f1.arrival_time||'?') + ' prices:' + JSON.stringify(prices1));
        console.log('    Leg 2: ' + f2.flight_id + ' dep:' + (f2.departure_time||'?') + ' arr:' + (f2.arrival_time||'?') + ' prices:' + JSON.stringify(prices2));
        console.log('    ' + timeOk);
      }
    }
  }
}
"

