tool_input_args.value:
cd /workspace && node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

const flightsFull = db.prepare(\"SELECT flight_id, origin, destination, departure_time, arrival_time, cabin_prices_json, dates_json FROM flights WHERE source_skill='tau2Airline'\").all();

// Build all valid one-stop pairs (where timing works)
const results = [];
for (const f1 of flightsFull) {
  for (const f2 of flightsFull) {
    if (f1.destination === f2.origin && f2.destination !== f1.origin) {
      // Check time compatibility
      if (f1.arrival_time && f2.departure_time && f1.arrival_time > f2.departure_time) continue;

      // Check shared available dates
      const dates1 = Object.entries(JSON.parse(f1.dates_json));
      const dates2 = JSON.parse(f2.dates_json);
      const sharedDates = dates1
        .filter(([d, info]) => info.status === 'available' && dates2[d] && dates2[d].status === 'available')
        .map(([d]) => d);

      if (sharedDates.length === 0) continue;

      const prices1 = JSON.parse(f1.cabin_prices_json);
      const prices2 = JSON.parse(f2.cabin_prices_json);

      // Find common cabin classes
      const commonCabins = Object.keys(prices1).filter(c => c in prices2);

      results.push({
        route: f1.origin + ' -> ' + f1.destination + ' -> ' + f2.destination,
        leg1: { flight: f1.flight_id, from: f1.origin, to: f1.destination, dep: f1.departure_time || 'TBD', arr: f1.arrival_time || 'TBD', prices: prices1 },
        leg2: { flight: f2.flight_id, from: f2.origin, to: f2.destination, dep: f2.departure_time || 'TBD', arr: f2.arrival_time || 'TBD', prices: prices2 },
        availableDates: sharedDates,
        cabinOptions: commonCabins.map(c => ({ cabin: c, leg1Price: prices1[c], leg2Price: prices2[c], totalPerPassenger: prices1[c] + prices2[c] }))
      });
    }
  }
}

console.log(JSON.stringify(results, null, 2));
console.log('Total one-stop options:', results.length);
"

